                        Input Schema
                      </summary>
                      <pre
                        style={{
                          marginTop: "10px",
                          padding: "10px",
                          backgroundColor: "#ffffff",
                          border: "1px solid #dee2e6",
                          borderRadius: "4px",
                          overflow: "auto",
                          fontSize: "0.8em",
