                  This MCP server does not support the resources/list method.
                </p>
              </div>
            ) : (
              resources.map((resource, index) => (
                <div
                  key={index}
                  style={{
                    border: "1px solid #dee2e6",
                    borderRadius: "4px",
                    padding: "10px",
                    marginBottom: "10px",
                    backgroundColor: "#f8f9fa",
                  }}
                >
                  <strong>{resource.name || resource.uri}</strong>
