import { Button } from "@/client/components/ui/button";
import { Label } from "@/client/components/ui/label";
import { Checkbox } from "@/client/components/ui/checkbox";
import type { ElicitResult } from "@mcp-use/client/react";
import type { PendingElicitationRequest } from "@/client/types/pending-requests";
import { JSONDisplay } from "@/client/components/shared/JSONDisplay";
import { toast } from "sonner";
import {
  Check,
  Copy,
  Download,
  Maximize2,
  X,
  ExternalLink,
} from "lucide-react";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/client/components/ui/tooltip";
import { Badge } from "@/client/components/ui/badge";
import { ElicitationFormFields } from "./shared/ElicitationFormFields";
import { useElicitationForm } from "./shared/useElicitationForm";
import { createElement } from "react";

interface ElicitationRequestDisplayProps {
  request: PendingElicitationRequest | null;
  onApprove: (requestId: string, result: ElicitResult) => void;
  onReject: (requestId: string, error?: string) => void;
  onClose: () => void;
  previewMode: boolean;
  onTogglePreview: () => void;
  isCopied: boolean;
  onCopy: () => void;
  onDownload: () => void;
  onFullscreen: () => void;
}

export function ElicitationRequestDisplay({
  request,
  onApprove,
  onReject,
  onClose,
  previewMode: _previewMode,
  onTogglePreview: _onTogglePreview,
  isCopied,
  onCopy,
  onDownload,
  onFullscreen,
}: ElicitationRequestDisplayProps) {
  const {
    formData,
    setFieldValue,
    getMissingRequiredFields,
    urlCompleted,
    setUrlCompleted,
    mode,
    isFormMode,
    isUrlMode,
  } = useElicitationForm(request);

  const handleAccept = () => {
    if (!request) return;

    if (isFormMode) {
      const missingFields = getMissingRequiredFields();
      if (missingFields.length > 0) {
        toast.error("Missing required fields", {
          description: `Please fill in: ${missingFields.join(", ")}`,
        });
        return;
      }

      onApprove(request.id, {
        action: "accept",
        content: formData,
      });
    } else if (isUrlMode) {
      onApprove(request.id, {
        action: "accept",
      });
    }
    onClose();

    const toastId = toast(
      createElement(
        "div",
        { className: "space-y-3" },
        createElement(
          "div",
          null,
          createElement("strong", null, "Elicitation Response Sent"),
          createElement(
            "p",
            { className: "text-sm text-muted-foreground mt-1" },
            "The tool will continue executing."
          )
        ),
        createElement(
          "div",
          { className: "flex gap-2" },
          createElement(
            "button",
            {
              "data-testid": "elicitation-view-tool-result",
              className:
                "px-3 py-1.5 text-xs font-medium rounded-md bg-primary text-primary-foreground hover:bg-primary/90",
              onClick: () => {
                const event = new globalThis.CustomEvent(
                  "navigate-to-tool-result",
                  {
                    detail: { toolName: null },
                  }
                );
                window.dispatchEvent(event);
                toast.dismiss(toastId);
              },
            },
            "View Tool Result"
          )
        )
      ),
      {
        duration: 5000,
      }
    );
  };

  const handleDecline = () => {
    if (!request) return;
    onApprove(request.id, { action: "decline" });
    onClose();
  };

  const handleCancel = () => {
    if (!request) return;
    onReject(request.id, "User cancelled elicitation request");
    onClose();
  };

  const handleOpenUrl = () => {
    if (request && isUrlMode && "url" in request.request) {
      window.open(request.request.url, "_blank");
      setUrlCompleted(true);
    }
  };

  if (!request) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-4 text-center">
        <p className="text-gray-500 dark:text-gray-400">
          Select an elicitation request to view details
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <div className="flex items-center justify-between p-4 border-b dark:border-zinc-700">
        <div className="flex items-center gap-2">
          <h3 className="font-medium text-gray-900 dark:text-gray-100">
            {request.serverName}
          </h3>
          <Badge
            variant="outline"
            className={
              isUrlMode
                ? "bg-blue-500/20 text-blue-600 dark:text-blue-400 border-blue-500/50"
                : "bg-green-500/20 text-green-600 dark:text-green-400 border-green-500/50"
            }
          >
            {mode}
          </Badge>
          <span className="text-sm text-gray-500 dark:text-gray-400">
            {new Date(request.timestamp).toLocaleString()}
          </span>
        </div>
        <div className="flex items-center gap-2">
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={onCopy}
                  className="h-8 w-8 p-0"
                >
                  {isCopied ? (
                    <Check className="h-4 w-4 text-green-600" />
                  ) : (
                    <Copy className="h-4 w-4" />
                  )}
                </Button>
              }
              nativeButton
            />
            <TooltipContent>Copy request</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={onDownload}
                  className="h-8 w-8 p-0"
                >
                  <Download className="h-4 w-4" />
                </Button>
              }
              nativeButton
            />
            <TooltipContent>Download request</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={onFullscreen}
                  className="h-8 w-8 p-0"
                >
                  <Maximize2 className="h-4 w-4" />
                </Button>
              }
              nativeButton
            />
            <TooltipContent>Fullscreen</TooltipContent>
          </Tooltip>
          <Button
            variant="ghost"
            size="sm"
            onClick={onClose}
            className="h-8 w-8 p-0"
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        <div className="space-y-2">
          <h4 className="text-sm font-semibold text-gray-900 dark:text-gray-100">
            Message
          </h4>
          <p className="text-sm text-gray-700 dark:text-gray-300">
            {request.request.message}
          </p>
        </div>

        {isUrlMode && "url" in request.request && (
          <div className="space-y-2">
            <h4 className="text-sm font-semibold text-gray-900 dark:text-gray-100">
              External Action Required
            </h4>
            <div className="bg-muted rounded-lg p-4 space-y-3">
              <p className="text-sm text-muted-foreground">
                This request requires you to complete an action at an external
                URL:
              </p>
              <div className="flex items-center gap-2 p-2 bg-background rounded border">
                <code className="flex-1 text-xs font-mono break-all">
                  {request.request.url}
                </code>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={handleOpenUrl}
                  className="flex items-center gap-2"
                >
                  <ExternalLink className="h-4 w-4" />
                  Open URL
                </Button>
              </div>
              <div className="flex items-center space-x-2 pt-2">
                <Checkbox
                  id="url-completed"
                  checked={urlCompleted}
                  onCheckedChange={(checked) => setUrlCompleted(!!checked)}
                />
                <Label
                  htmlFor="url-completed"
                  className="text-sm font-normal cursor-pointer"
                >
                  I have completed the required action
                </Label>
              </div>
            </div>
          </div>
        )}

        {isFormMode && (
          <div className="space-y-2">
            <h4 className="text-sm font-semibold text-gray-900 dark:text-gray-100">
              Form Data
            </h4>
            <ElicitationFormFields
              request={request}
              formData={formData}
              onFieldChange={setFieldValue}
              idPrefix="field"
              testIdPrefix="elicitation-field"
              emptyFallback={
                <div className="text-sm text-gray-500 dark:text-gray-400">
                  No form schema available
                </div>
              }
            />
          </div>
        )}

        {isFormMode &&
          "requestedSchema" in request.request &&
          request.request.requestedSchema && (
            <details className="space-y-2">
              <summary className="text-sm font-semibold text-gray-900 dark:text-gray-100 cursor-pointer">
                Schema (for reference)
              </summary>
              <div className="bg-muted rounded-lg p-3 max-h-64 overflow-auto">
                <JSONDisplay data={request.request.requestedSchema} />
              </div>
            </details>
          )}
      </div>

      <div className="flex gap-2 p-4 border-t dark:border-zinc-700">
        <Button
          onClick={handleAccept}
          className="flex-1"
          disabled={isUrlMode && !urlCompleted}
          data-testid="elicitation-accept-button"
        >
          Accept
        </Button>
        <Button
          onClick={handleDecline}
          variant="outline"
          className="flex-1"
          data-testid="elicitation-decline-button"
        >
          Decline
        </Button>
        <Button
          onClick={handleCancel}
          variant="outline"
          className="flex-1"
          data-testid="elicitation-cancel-button"
        >
          Cancel
        </Button>
      </div>
    </div>
  );
}

import type { PendingElicitationRequest } from "@/client/types/pending-requests";
import { ListItem } from "@/client/components/shared/ListItem";
import { NotFound } from "@/client/components/ui/not-found";
import { Badge } from "@/client/components/ui/badge";

interface ElicitationRequestsListProps {
  requests: PendingElicitationRequest[];
  selectedRequest: PendingElicitationRequest | null;
  onRequestSelect: (request: PendingElicitationRequest) => void;
  focusedIndex: number;
  formatRelativeTime: (timestamp: number) => string;
}

export function ElicitationRequestsList({
  requests,
  selectedRequest,
  onRequestSelect,
  focusedIndex,
  formatRelativeTime,
}: ElicitationRequestsListProps) {
  if (requests.length === 0) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center p-4 text-center">
        <NotFound vertical noBorder message="No elicitation requests" />
      </div>
    );
  }

  return (
    <div>
      {requests.map((request, index) => {
        const mode = request.request.mode || "form";
        const hasSchema =
          mode === "form" &&
          "requestedSchema" in request.request &&
          request.request.requestedSchema;

        return (
          <ListItem
            key={request.id}
            id={`elicitation-request-${request.id}`}
            data-testid={`elicitation-request-item-${index}`}
            isSelected={selectedRequest?.id === request.id}
            isFocused={focusedIndex === index}
            title={
              <span className="flex items-center gap-3">
                {request.serverName}
                <Badge
                  variant="outline"
                  className={
                    mode === "url"
                      ? "bg-blue-500/20 text-blue-600 dark:text-blue-400 border-blue-500/50"
                      : "bg-green-500/20 text-green-600 dark:text-green-400 border-green-500/50"
                  }
                >
                  {mode}
                </Badge>
              </span>
            }
            description={(() => {
              const timeStr = formatRelativeTime(request.timestamp);
              const details = [];
              if (hasSchema) {
                details.push("with schema");
              }
              if (mode === "url") {
                details.push("external action");
              }
              const detailsStr =
                details.length > 0 ? ` | ${details.join(", ")}` : "";
              return timeStr + detailsStr;
            })()}
            onClick={() => onRequestSelect(request)}
          />
        );
      })}
    </div>
  );
}

import { useMemo, useState } from "react";
import type { ElicitResult } from "@mcp-use/client/react";
import { ExternalLink } from "lucide-react";
import { toast } from "sonner";
import type { PendingElicitationRequest } from "@/client/types/pending-requests";
import {
  AskUserQuestions,
  type AskUserAnswer,
} from "@/client/components/ui/ask-user-questions";
import { Button } from "@/client/components/ui/button";
import {
  answersToFormData,
  elicitationToAskUserQuestions,
  getMissingRequiredFromAnswers,
  schemaToDefaultAnswers,
} from "./elicitationToAskUserQuestions";

interface ElicitationAskUserPanelProps {
  request: PendingElicitationRequest;
  onApprove: (requestId: string, result: ElicitResult) => void;
  onReject: (requestId: string, error?: string) => void;
  testId?: string;
  actionTestIdPrefix?: string;
}

export function ElicitationAskUserPanel({
  request,
  onApprove,
  onReject,
  testId = "inline-elicitation",
  actionTestIdPrefix = "inline-elicitation",
}: ElicitationAskUserPanelProps) {
  const [responded, setResponded] = useState(false);
  const [responseLabel, setResponseLabel] = useState("");

  const questions = useMemo(
    () => elicitationToAskUserQuestions(request.request),
    [request.request]
  );

  const defaultAnswers = useMemo(
    () => schemaToDefaultAnswers(questions, request.request),
    [questions, request.request]
  );

  const mode = request.request.mode || "form";
  const isUrlMode = mode === "url";
  const url =
    isUrlMode && "url" in request.request ? request.request.url : undefined;

  const finish = (label: string, result: ElicitResult) => {
    setResponded(true);
    setResponseLabel(label);
    onApprove(request.id, result);
  };

  const handleComplete = (answers: Record<string, AskUserAnswer>) => {
    if (responded) return;

    if (isUrlMode) {
      const confirmed =
        answers.__url_confirm__?.selectedIds.includes("confirmed");
      if (!confirmed) {
        toast.error("Confirm you've completed the external action");
        return;
      }
      finish("accepted", { action: "accept" });
      return;
    }

    const missing = getMissingRequiredFromAnswers(
      questions,
      answers,
      request.request
    );
    if (missing.length > 0) {
      toast.error("Missing required fields", {
        description: `Please fill in: ${missing.join(", ")}`,
      });
      return;
    }

    finish("accepted", {
      action: "accept",
      content: answersToFormData(
        questions,
        answers,
        request.request
      ) as ElicitResult["content"],
    });
  };

  if (responded) {
    return (
      <p
        className="text-sm text-muted-foreground"
        data-testid={`${testId}-responded`}
      >
        Elicitation {responseLabel} — the tool will continue executing.
      </p>
    );
  }

  const intro = (
    <div className="space-y-2">
      <p className="text-foreground/90">{request.request.message}</p>
      {isUrlMode && url && (
        <div className="flex items-center gap-2 rounded-md border bg-muted/40 p-2">
          <code className="flex-1 text-xs font-mono break-all">{url}</code>
          <Button
            size="sm"
            variant="outline"
            onClick={() => window.open(url, "_blank")}
            data-testid={`${actionTestIdPrefix}-open-url`}
          >
            <ExternalLink className="h-3 w-3 mr-1" />
            Open
          </Button>
        </div>
      )}
    </div>
  );

  return (
    <AskUserQuestions
      questions={questions}
      defaultAnswers={defaultAnswers}
      onComplete={handleComplete}
      intro={intro}
      onCancel={() =>
        onReject(request.id, "User cancelled elicitation request")
      }
      cancelLabel="Cancel"
      footerLeading={
        <button
          type="button"
          className="shrink-0 cursor-pointer text-[12px] text-muted-foreground underline-offset-2 hover:text-foreground hover:underline"
          onClick={() => finish("declined", { action: "decline" })}
          data-testid={`${actionTestIdPrefix}-decline-button`}
        >
          Decline
        </button>
      }
      className="w-full max-w-none shadow-lg"
      data-testid={testId}
    />
  );
}

import { useMemo } from "react";
import type { PendingElicitationRequest } from "@/client/types/pending-requests";
import { Input } from "@/client/components/ui/input";
import { Label } from "@/client/components/ui/label";
import { Textarea } from "@/client/components/ui/textarea";
import { Checkbox } from "@/client/components/ui/checkbox";
import { getMultiSelectChoices, getSingleSelectChoices } from "./schemaHelpers";

interface ElicitationFormFieldsProps {
  request: PendingElicitationRequest;
  formData: Record<string, any>;
  onFieldChange: (fieldName: string, value: any) => void;
  /** Prefix used for DOM `id` attributes (e.g. `"field"` → `"field-{name}"`). */
  idPrefix: string;
  /** Prefix used for `data-testid` attributes (e.g. `"elicitation-field"`). */
  testIdPrefix: string;
  /** Class for the per-field vertical spacing. */
  fieldContainerClassName?: string;
  /** Row count for textarea fields. */
  textareaRows?: number;
  /** Whether to render the outer label above a boolean field (in addition to the checkbox-adjacent label). */
  showOuterLabelForBoolean?: boolean;
  /** Fallback rendered when the schema is missing or malformed. */
  emptyFallback?: React.ReactNode;
}

export function ElicitationFormFields({
  request,
  formData,
  onFieldChange,
  idPrefix,
  testIdPrefix,
  fieldContainerClassName = "space-y-2",
  textareaRows = 4,
  showOuterLabelForBoolean = true,
  emptyFallback,
}: ElicitationFormFieldsProps) {
  const rendered = useMemo(() => {
    if (!("requestedSchema" in request.request)) return null;

    const schema = request.request.requestedSchema;
    if (!schema || schema.type !== "object" || !schema.properties) {
      return (
        emptyFallback ?? (
          <p className="text-sm text-muted-foreground">
            No form schema available
          </p>
        )
      );
    }

    const properties = schema.properties as Record<string, any>;
    const required = (schema.required as string[]) || [];

    return (
      <div className="space-y-4">
        {Object.entries(properties).map(([fieldName, fieldSchema]) => {
          const field = fieldSchema as any;
          const isRequired = required.includes(fieldName);
          const fieldType = field.type || "string";
          const fieldLabel = field.title || fieldName;
          const fieldDescription = field.description;
          const singleSelectChoices = getSingleSelectChoices(field);
          const isSingleSelectChoiceField = singleSelectChoices.length > 0;
          const isEnumField = Array.isArray(field.enum);
          const isUntitledMultiSelectField =
            fieldType === "array" && Array.isArray(field.items?.enum);
          const multiSelectChoices = getMultiSelectChoices(field);
          const isTitledMultiSelectField =
            fieldType === "array" && multiSelectChoices.length > 0;
          const selectedMultiValues = Array.isArray(formData[fieldName])
            ? (formData[fieldName] as string[])
            : [];

          const inputId = `${idPrefix}-${fieldName}`;
          const testId = `${testIdPrefix}-${fieldName}`;
          const showTopLabel =
            fieldType !== "boolean" || showOuterLabelForBoolean;

          return (
            <div key={fieldName} className={fieldContainerClassName}>
              {showTopLabel && (
                <Label htmlFor={inputId}>
                  {fieldLabel}
                  {isRequired && <span className="text-red-500 ml-1">*</span>}
                </Label>
              )}
              {fieldDescription && (
                <p className="text-xs text-muted-foreground">
                  {fieldDescription}
                </p>
              )}

              {fieldType === "boolean" ? (
                <div className="flex items-center space-x-2">
                  <Checkbox
                    id={inputId}
                    data-testid={testId}
                    checked={formData[fieldName] || false}
                    onCheckedChange={(checked) =>
                      onFieldChange(fieldName, checked)
                    }
                  />
                  <Label
                    htmlFor={inputId}
                    className="text-sm font-normal cursor-pointer"
                  >
                    {fieldLabel}
                    {!showOuterLabelForBoolean && isRequired && (
                      <span className="text-red-500 ml-1">*</span>
                    )}
                  </Label>
                </div>
              ) : fieldType === "number" || fieldType === "integer" ? (
                <Input
                  id={inputId}
                  data-testid={testId}
                  type="number"
                  value={formData[fieldName] ?? ""}
                  onChange={(e) => {
                    const parsed =
                      fieldType === "integer"
                        ? parseInt(e.target.value, 10)
                        : parseFloat(e.target.value);
                    onFieldChange(fieldName, isNaN(parsed) ? "" : parsed);
                  }}
                  placeholder={field.default?.toString() || ""}
                />
              ) : isSingleSelectChoiceField ? (
                <select
                  id={inputId}
                  data-testid={testId}
                  value={formData[fieldName] || ""}
                  onChange={(e) => onFieldChange(fieldName, e.target.value)}
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                >
                  <option value="">Select...</option>
                  {singleSelectChoices.map((choice) => (
                    <option key={choice.const} value={choice.const}>
                      {choice.title || choice.const}
                    </option>
                  ))}
                </select>
              ) : isEnumField ? (
                <select
                  id={inputId}
                  data-testid={testId}
                  value={formData[fieldName] || ""}
                  onChange={(e) => onFieldChange(fieldName, e.target.value)}
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                >
                  <option value="">Select...</option>
                  {field.enum.map((option: string, index: number) => (
                    <option key={option} value={option}>
                      {field.enumNames?.[index] || option}
                    </option>
                  ))}
                </select>
              ) : isUntitledMultiSelectField ? (
                <div className="space-y-2" data-testid={testId}>
                  {field.items.enum.map((option: string) => {
                    const checkboxId = `${inputId}-${option}`;
                    const checked = selectedMultiValues.includes(option);
                    return (
                      <div key={option} className="flex items-center space-x-2">
                        <Checkbox
                          id={checkboxId}
                          checked={checked}
                          onCheckedChange={(nextChecked) => {
                            const updated = nextChecked
                              ? [...selectedMultiValues, option]
                              : selectedMultiValues.filter(
                                  (value) => value !== option
                                );
                            onFieldChange(fieldName, updated);
                          }}
                        />
                        <Label
                          htmlFor={checkboxId}
                          className="text-sm font-normal cursor-pointer"
                        >
                          {option}
                        </Label>
                      </div>
                    );
                  })}
                </div>
              ) : isTitledMultiSelectField ? (
                <div className="space-y-2" data-testid={testId}>
                  {multiSelectChoices.map((choice) => {
                    const checkboxId = `${inputId}-${choice.const}`;
                    const checked = selectedMultiValues.includes(choice.const);
                    return (
                      <div
                        key={choice.const}
                        className="flex items-center space-x-2"
                      >
                        <Checkbox
                          id={checkboxId}
                          checked={checked}
                          onCheckedChange={(nextChecked) => {
                            const updated = nextChecked
                              ? [...selectedMultiValues, choice.const]
                              : selectedMultiValues.filter(
                                  (value) => value !== choice.const
                                );
                            onFieldChange(fieldName, updated);
                          }}
                        />
                        <Label
                          htmlFor={checkboxId}
                          className="text-sm font-normal cursor-pointer"
                        >
                          {choice.title || choice.const}
                        </Label>
                      </div>
                    );
                  })}
                </div>
              ) : fieldType === "string" &&
                (field.format === "textarea" || field.maxLength > 100) ? (
                <Textarea
                  id={inputId}
                  data-testid={testId}
                  value={formData[fieldName] || ""}
                  onChange={(e) => onFieldChange(fieldName, e.target.value)}
                  placeholder={field.default || ""}
                  rows={textareaRows}
                />
              ) : (
                <Input
                  id={inputId}
                  data-testid={testId}
                  type="text"
                  value={formData[fieldName] || ""}
                  onChange={(e) => onFieldChange(fieldName, e.target.value)}
                  placeholder={field.default || ""}
                />
              )}
            </div>
          );
        })}
      </div>
    );
  }, [
    request,
    formData,
    onFieldChange,
    idPrefix,
    testIdPrefix,
    fieldContainerClassName,
    textareaRows,
    showOuterLabelForBoolean,
    emptyFallback,
  ]);

  return <>{rendered}</>;
}

/**
 * CommonJS host loading ESM-only @mcp-use/client via dynamic import().
 *
 * Defaults to the local demo HTTP server. Override with MCP_SERVER_URL, or set
 * USE_STDIO_EVERYTHING=1 to use npx @modelcontextprotocol/server-everything.
 *
 *   MCP_SERVER_URL=http://127.0.0.1:3101/mcp node examples/browser/commonjs/commonjs_example.cjs
 *   MCP_SERVER_URL=http://127.0.0.1:3102/mcp node examples/browser/commonjs/commonjs_example.cjs
 */

async function runCommonJSExample() {
  const { MCPClient } = await import("@mcp-use/client");
  console.log("=== CommonJS MCP Example ===\n");

  const useStdio = process.env.USE_STDIO_EVERYTHING === "1";
  const url = process.env.MCP_SERVER_URL ?? "http://127.0.0.1:3102/mcp";

  const client = new MCPClient({
    mcpServers: useStdio
      ? {
          everything: {
            command: "npx",
            args: ["-y", "@modelcontextprotocol/server-everything"],
          },
        }
      : {
          demo: { url },
        },
  });

  try {
    const name = useStdio ? "everything" : "demo";
    const connection = await client.connect(name);
    console.log("✓ Connected", `(era=${connection.protocolEra ?? "?"})`);

    const tools = await connection.listTools();
    console.log(`✓ Found ${tools.length} tools`);
    for (const tool of tools.slice(0, 5)) {
      console.log(`  - ${tool.name}`);
    }

    if (tools.some((t) => t.name === "echo")) {
      const result = await connection.callTool("echo", { message: "cjs" });
      console.log("✓ echo ->", JSON.stringify(result.content));
    }

    console.log("\n=== CommonJS Example Completed Successfully ===");
  } catch (error) {
    console.error("Error:", error.message);
    process.exitCode = 1;
  } finally {
    await client.close();
  }
}

runCommonJSExample().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

